package com.aadil.ecommerce.exceptions;import com.aadil.ecommerce.responses.APIResponse;import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.ExceptionHandler;import org.springframework.web.bind.annotation.RestControllerAdvice;import java.time.LocalDateTime;@RestControllerAdvicepublic class GlobalExceptionHandler {    @ExceptionHandler(UserAlreadyExistsException.class)    public ResponseEntity<APIResponse<HttpStatus>> handlesAlreadyExists(UserAlreadyExistsException existsException){        APIResponse<HttpStatus> apiResponse = new APIResponse<>();        apiResponse.setSuccess(false);        apiResponse.setCode(HttpStatus.CONFLICT);        apiResponse.setMessage(existsException.getMessage());        apiResponse.setData(null);        apiResponse.setTimeStamp(LocalDateTime.now());        return ResponseEntity.status(409).body(apiResponse);    }}